static inline int xSemaphoreTake(SemaphoreHandle_t, uint32_t) { return pdTRUE; }
static inline int xSemaphoreGive(SemaphoreHandle_t) { return pdTRUE; }
static inline uint32_t uxTaskGetStackHighWaterMark(TaskHandle_t) { return 4096; }

// ---- virtual time + signal model ------------------------------------------------------
static uint64_t g_mockUs = 5000000ULL;   // start at 5 s so nothing depends on t=0

enum SimMode { SIM_IDLE = 0, SIM_BALL = 1, SIM_STUCK_ACTIVE = 2, SIM_NOISE = 3 };
static int g_simMode[16];                 // per mux channel
static int g_simPeriodUs = 833;           // 1.2 kHz ball modulation
static int g_simActiveUs = 350;           // output LOW for this long each period (TSOP active-low)
static uint64_t g_simPhase[16];           // per-channel pulse phase offset (us), randomised by the benchmarks
static int g_simChPeriod[16];             // per-channel source period override (us), 0 = use g_simPeriodUs
static int g_simNoiseUs = 120;            // interference toggle period
static bool g_simActiveHigh[16];          // model a channel whose output idles LOW and pulses HIGH

static uint8_t g_pinLevel[64];
static uint8_t g_pinMode[64];
static void (*g_isrFn)() = nullptr;
static uint8_t g_lastSigLevel = 1;
static uint32_t g_isrCalls = 0;

static int mockMuxChannel() {
  return (g_pinLevel[4] ? 1 : 0) | (g_pinLevel[13] ? 2 : 0) | (g_pinLevel[15] ? 4 : 0) | (g_pinLevel[2] ? 8 : 0);
}
static uint8_t mockSigLevel(uint64_t us) {
  int ch = mockMuxChannel();
  bool activeHigh = g_simActiveHigh[ch];
  bool active = false;
  switch (g_simMode[ch]) {
    case SIM_BALL: { int per = g_simChPeriod[ch] ? g_simChPeriod[ch] : g_simPeriodUs; int act = g_simChPeriod[ch] ? (per * 42) / 100 : g_simActiveUs;
                     active = (int)((us + (uint64_t)ch * 97u + g_simPhase[ch]) % (uint64_t)per) < act; break; }
    case SIM_STUCK_ACTIVE: active = true; break;
    case SIM_NOISE: active = (int)((us / (uint64_t)g_simNoiseUs) & 1u); break;
    default: active = false;
  }
  return (uint8_t)(active ? (activeHigh ? 1 : 0) : (activeHigh ? 0 : 1));
}

// Serial TX model: 115200 8N1 ~ 11520 B/s, 2048 B buffer
static double g_serialRoom = 2048;
static bool g_serialUnlimited = false;
static void mockAdvance(uint32_t us) {
  uint32_t left = us;
  while (left) {
    uint32_t step = left > 10 ? 10 : left;
    left -= step;
    g_mockUs += step;
    g_serialRoom = std::min(2048.0, g_serialRoom + step * 0.01152);
    uint8_t lvl = mockSigLevel(g_mockUs);
    if (lvl != g_lastSigLevel) {
      g_lastSigLevel = lvl;
      if (g_isrFn) { g_isrCalls++; g_isrFn(); }
    }
  }
}
static inline uint32_t millis() { return (uint32_t)(g_mockUs / 1000ULL); }
static inline uint32_t micros() { return (uint32_t)g_mockUs; }
static inline void delay(uint32_t ms) { mockAdvance(ms * 1000u); }
static inline void delayMicroseconds(uint32_t us) { mockAdvance(us); }
static inline void yield() {}

// ---- GPIO --------------------------------------------------------------------------------
static inline void pinMode(uint8_t p, uint8_t m) { g_pinMode[p] = m; }
static inline void digitalWrite(uint8_t p, uint8_t v) { g_pinLevel[p] = v ? 1 : 0; }
static inline int digitalRead(uint8_t p) {
  if (p == 34) return mockSigLevel(g_mockUs);
  if (p == 16 || p == 17) return 1;
  return g_pinLevel[p];
}
static inline uint8_t digitalPinToInterrupt(uint8_t p) { return p; }
static inline void attachInterrupt(uint8_t, void (*fn)(), int) { g_isrFn = fn; }

// ---- LEDC -----------------------------------------------------------------------------------
static uint32_t g_pwmDuty[64];
static bool g_ledcFail = false;
static uint32_t g_ledcFreq = 0;
#if MOCK_CORE_V3
static inline bool ledcAttach(uint8_t pin, uint32_t freq, uint8_t) { if (g_ledcFail) return false; g_ledcFreq = freq; g_pwmDuty[pin] = 0; return true; }
static inline bool ledcWrite(uint8_t pin, uint32_t duty) { g_pwmDuty[pin] = duty; return true; }
#else
static uint8_t g_chPin[16];
static inline uint32_t ledcSetup(uint8_t, uint32_t freq, uint8_t) { if (g_ledcFail) return 0; g_ledcFreq = freq; return freq; }
static inline void ledcAttachPin(uint8_t pin, uint8_t ch) { g_chPin[ch] = pin; }
static inline void ledcWrite(uint8_t ch, uint32_t duty) { g_pwmDuty[g_chPin[ch]] = duty; }
#endif

// ---- Serial -----------------------------------------------------------------------------------
struct MockSerial {
  std::string out;
  std::deque<uint8_t> in;
  bool begun = false;
  void begin(unsigned long) { begun = true; }
  size_t setTxBufferSize(size_t n) { return n; }
  int availableForWrite() { return g_serialUnlimited ? 4096 : (int)g_serialRoom; }
  size_t write(const uint8_t* b, size_t n) {
    out.append((const char*)b, n);
    if (!g_serialUnlimited) g_serialRoom = std::max(0.0, g_serialRoom - (double)n);
    return n;
  }
  int available() { return (int)in.size(); }
  int read() { if (in.empty()) return -1; int v = in.front(); in.pop_front(); return v; }
  void feed(const std::string& s) { for (unsigned char c : s) in.push_back(c); }
};
static MockSerial Serial;

// ---- MPU6050 model on I2C ------------------------------------------------------------------------
struct MockMpu {
  bool present = true;
  uint8_t addr = 0x68;
  uint8_t whoami = 0x68;
  int mode = 0;            // 0 normal, 1 NACK, 2 frozen frame, 3 all-zero frame, 4 gyro saturated
  float gz = 0, gx = 0, gy = 0, azg = 1.0f;
  uint8_t regs[128];
  uint32_t reads = 0, initWrites = 0;
  int16_t frozen[7];
  bool haveFrozen = false;
};
static MockMpu g_mpu;
struct MockWire {
  uint8_t cur = 0;
  std::vector<uint8_t> tx, rx;
  size_t rxPos = 0;
  uint8_t regPtr = 0;
  bool begun = false;
  int beginCalls = 0;
  bool begin(int, int, uint32_t) { begun = true; beginCalls++; return true; }
  void end() { begun = false; }
  void setTimeOut(uint16_t) {}
  void beginTransmission(uint8_t a) { cur = a; tx.clear(); }
  size_t write(uint8_t b) { tx.push_back(b); return 1; }
  uint8_t endTransmission(bool stop = true) {
    if (!g_mpu.present || cur != g_mpu.addr || g_mpu.mode == 1) return 2;
    if (tx.size() >= 2) { g_mpu.regs[tx[0] & 127] = tx[1]; g_mpu.initWrites++; }
    else if (tx.size() == 1) regPtr = tx[0];
    (void)stop;
    return 0;
  }
  size_t requestFrom(uint8_t a, size_t n, bool) {
    rx.clear(); rxPos = 0;
    if (!g_mpu.present || a != g_mpu.addr || g_mpu.mode == 1) return 0;
    if (regPtr == 0x75) { rx.push_back(g_mpu.whoami); }
    else if (regPtr == 0x3B) {
      g_mpu.reads++;
      int16_t r[7];
      auto cl = [](float v) { return (int16_t)std::max(-32767.0f, std::min(32767.0f, v)); };
      r[0] = 0; r[1] = 0; r[2] = cl(g_mpu.azg * 8192.0f); r[3] = 0x0800;
      r[4] = cl(g_mpu.gx * 65.5f); r[5] = cl(g_mpu.gy * 65.5f); r[6] = cl(g_mpu.gz * 65.5f);
      static uint32_t lcg = 1234567u;                       // sensor noise: a real MPU6050 never repeats a frame exactly
      for (int i = 0; i < 7; i++) { lcg = lcg * 1664525u + 1013904223u; if (i != 3) r[i] = (int16_t)(r[i] + (int)((lcg >> 24) % 7u) - 3); }
      if (g_mpu.mode == 3) memset(r, 0, sizeof(r));
      if (g_mpu.mode == 4) r[6] = -32768;
      if (g_mpu.mode == 2) { if (!g_mpu.haveFrozen) { memcpy(g_mpu.frozen, r, sizeof(r)); g_mpu.haveFrozen = true; } memcpy(r, g_mpu.frozen, sizeof(r)); }
      else g_mpu.haveFrozen = false;
      for (int i = 0; i < 7; i++) { rx.push_back((uint8_t)(r[i] >> 8)); rx.push_back((uint8_t)(r[i] & 0xFF)); }
    }
    while (rx.size() < n) rx.push_back(0);
    rx.resize(n);
    return n;
  }
  int available() { return (int)(rx.size() - rxPos); }
  int read() { return rxPos < rx.size() ? rx[rxPos++] : -1; }
};
static MockWire Wire;

